function sandStep(s){
  var w=s.w,h=s.h,cells=s.cells,nc=Int8Array.from(cells);
  for(var y=h-1;y>=0;y--){ for(var x=0;x<w;x++){ var i=y*w+x; if(cells[i]!==1) continue;
    if(y+1<h){ var d=cells[(y+1)*w+x];
      if(d===0){ nc[i]=0; nc[(y+1)*w+x]=1; continue; }
      var dl = x>0 ? cells[(y+1)*w+x-1] : 9;
      var dr = x<w-1 ? cells[(y+1)*w+x+1] : 9;
      if(dl===0 && dr===0){ if(((x+(y&1))&1)===0){ nc[i]=0; nc[(y+1)*w+x-1]=1; } else { nc[i]=0; nc[(y+1)*w+x+1]=1; } }
      else if(dl===0){ nc[i]=0; nc[(y+1)*w+x-1]=1; }
      else if(dr===0){ nc[i]=0; nc[(y+1)*w+x+1]=1; }
    }
  } }
  return {w:w,h:h,cells:nc};
}
